// Package store provides typed repository wrappers for the database.
//
// In production these would be generated by sqlc from queries/*.sql +
// migrations/*.sql. We hand-write the same shape here so the project builds
// without requiring sqlc to be installed; when sqlc becomes available the
// generated `internal/store/sqlc/` package can replace these files 1:1.
//
// All read methods that touch tenant-scoped tables also expose
// `*ByTenant(ctx, tenantID, ...)` variants that pull tenant_id from
// context.Context via the tenant package. The store layer is the
// LAST line of defense against forgetting the tenant scope — the
// service layer should already have set it via auth middleware.
package store

import (
	"context"
	"errors"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/trading-journal/api/internal/domain/payment"
	"github.com/trading-journal/api/internal/domain/subscription"
)

// DBTX is the minimal interface satisfied by both *pgxpool.Pool and pgx.Tx.
// Lets repo methods run inside or outside a transaction.
type DBTX interface {
	Exec(ctx context.Context, sql string, args ...any) (pgconn.CommandTag, error)
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
}

// FromPool wraps a pool so it satisfies DBTX.
func FromPool(p *pgxpool.Pool) DBTX { return p }

// Store aggregates all per-table repositories.
type Store struct {
	Pool              *pgxpool.Pool
	Users             *UserRepo
	Tenants           *TenantRepo
	Memberships       *MembershipRepo
	Plans             *PlanRepo
	Subscriptions     *SubscriptionRepo
	Refresh           *RefreshSessionRepo
	Audit             *AuditLogRepo
	OAuthStates       *OAuthStateRepo
	UserIdentities    *UserIdentityRepo
	TradingAccounts   *TradingAccountRepo
	ImportedFiles     *ImportedFileRepo
	ImportJobs        *ImportJobRepo
	Deals             *DealRepo
	Positions         *PositionRepo
	Trades            *TradeRepo
	JournalEntries    *JournalEntryRepo
	Tags              *TagRepo
	TradeTags         *TradeTagsRepo
	TradeImages       *TradeImageRepo
	DailyMetrics      *DailyMetricRepo
	BrokerConnections *BrokerConnectionRepo
	SyncRuns          *SyncRunRepo
	Payments          *PaymentRepo
	ReportSchedules   *ReportScheduleRepo
	APIKeys           *APIKeyRepo
	WebhookSubs       *WebhookSubscriptionRepo
	WebhookDeliveries *WebhookDeliveryRepo
	WebhookEvents     *WebhookEventRepo
	TradeAnalyses     *TradeAnalysisRepo
	AIUsage           *AIUsageDailyRepo
	Recaps            *RecapRepo
	ChatThreads       *ChatThreadRepo
	ChatMessages      *ChatMessageRepo
	TradeEmbeddings   *TradeEmbeddingRepo
}

// New builds a Store with all repos wired to the given pool.
func New(pool *pgxpool.Pool) *Store {
	return &Store{
		Pool:              pool,
		Users:             &UserRepo{pool: pool},
		Tenants:           &TenantRepo{pool: pool},
		Memberships:       &MembershipRepo{pool: pool},
		Plans:             &PlanRepo{pool: pool},
		Subscriptions:     &SubscriptionRepo{pool: pool},
		Refresh:           &RefreshSessionRepo{pool: pool},
		Audit:             &AuditLogRepo{pool: pool},
		OAuthStates:       &OAuthStateRepo{pool: pool},
		UserIdentities:    &UserIdentityRepo{pool: pool},
		TradingAccounts:   &TradingAccountRepo{pool: pool},
		ImportedFiles:     &ImportedFileRepo{pool: pool},
		ImportJobs:        &ImportJobRepo{pool: pool},
		Deals:             &DealRepo{pool: pool},
		Positions:         &PositionRepo{pool: pool},
		Trades:            &TradeRepo{pool: pool},
		JournalEntries:    &JournalEntryRepo{pool: pool},
		Tags:              &TagRepo{pool: pool},
		TradeTags:         &TradeTagsRepo{pool: pool},
		TradeImages:       &TradeImageRepo{pool: pool},
		DailyMetrics:      &DailyMetricRepo{pool: pool},
		BrokerConnections: &BrokerConnectionRepo{pool: pool},
		SyncRuns:          &SyncRunRepo{pool: pool},
		Payments:          &PaymentRepo{pool: pool},
		ReportSchedules:   &ReportScheduleRepo{pool: pool},
		APIKeys:           &APIKeyRepo{pool: pool},
		WebhookSubs:       &WebhookSubscriptionRepo{pool: pool},
		WebhookDeliveries: &WebhookDeliveryRepo{pool: pool},
		WebhookEvents:     &WebhookEventRepo{pool: pool},
		TradeAnalyses:     &TradeAnalysisRepo{pool: pool},
		AIUsage:           &AIUsageDailyRepo{pool: pool},
		Recaps:            &RecapRepo{pool: pool},
		ChatThreads:       &ChatThreadRepo{pool: pool},
		ChatMessages:      &ChatMessageRepo{pool: pool},
		TradeEmbeddings:   &TradeEmbeddingRepo{pool: pool},
	}
}

// WithTx runs fn inside a database transaction and rolls back on error.
func (s *Store) WithTx(ctx context.Context, fn func(tx pgx.Tx) error) error {
	tx, err := s.Pool.Begin(ctx)
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback(ctx) }()
	if err := fn(tx); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

// ── Phase 7 — EventApplyStore passthrough methods ────────────────────────

// WebhookEventInsert inserts an event idempotency row.
func (s *Store) WebhookEventInsert(ctx context.Context, stripeEventID, eventType string) (bool, error) {
	return s.WebhookEvents.Insert(ctx, stripeEventID, eventType)
}

// SubscriptionUpsertByExternalID delegates to SubscriptionRepo.
func (s *Store) SubscriptionUpsertByExternalID(ctx context.Context, sub *subscription.Subscription) error {
	return s.Subscriptions.UpsertByExternalID(ctx, sub)
}

// SubscriptionGetByExternalID delegates to SubscriptionRepo.
func (s *Store) SubscriptionGetByExternalID(ctx context.Context, externalID string) (*subscription.Subscription, error) {
	return s.Subscriptions.GetByExternalID(ctx, externalID)
}

// PaymentUpsertByExternalInvoice delegates to PaymentRepo.
func (s *Store) PaymentUpsertByExternalInvoice(ctx context.Context, p *payment.Payment) error {
	return s.Payments.UpsertByExternalInvoice(ctx, p)
}

// IsUniqueViolation returns true if err is a Postgres unique-constraint
// violation (SQLSTATE 23505). Used by services to translate to typed errors.
func IsUniqueViolation(err error) bool {
	var pgErr *pgconn.PgError
	return errors.As(err, &pgErr) && pgErr.Code == "23505"
}

// IsForeignKeyViolation returns true if err is a FK violation (23503).
func IsForeignKeyViolation(err error) bool {
	var pgErr *pgconn.PgError
	return errors.As(err, &pgErr) && pgErr.Code == "23503"
}